function parseDate(s){ var p=String(s).split('-'); if(p.length!==3) return null; var d=new Date(Date.UTC(+p[0], +p[1]-1, +p[2])); return isNaN(d.getTime())?null:d; }
function fmt(d){ function z(n){return (n<10?'0':'')+n;} return d.getUTCFullYear()+'-'+z(d.getUTCMonth()+1)+'-'+z(d.getUTCDate()); }
function daysBetween(a, b){ var d1=parseDate(a), d2=parseDate(b); if(!d1||!d2) return NaN; return Math.round((d2-d1)/86400000); }
function addDays(a, n){ var d=parseDate(a); if(!d) return null; d=new Date(d.getTime()+n*86400000); return fmt(d); }
function weekday(a){ var d=parseDate(a); if(!d) return null; return ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d.getUTCDay()]; }
var EXPORTS = { parseDate:parseDate, fmt:fmt, daysBetween:daysBetween, addDays:addDays, weekday:weekday };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DateDiffForgePure = EXPORTS; }
